create table if not exists public.businesses(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,name text not null,industry text,location text,website text,offer text,audience text,goal text,budget text,created_at timestamptz default now());
create table if not exists public.campaigns(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,objective text,status text default 'DRAFT',strategy jsonb,created_at timestamptz default now());
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text,source text,status text default 'New',score integer,value text,created_at timestamptz default now());
create table if not exists public.automations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text,trigger text,status text default 'DRAFT',config jsonb,created_at timestamptz default now());
alter table public.businesses enable row level security; alter table public.campaigns enable row level security; alter table public.leads enable row level security; alter table public.automations enable row level security;
drop policy if exists "business own" on public.businesses; create policy "business own" on public.businesses for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "campaign own" on public.campaigns; create policy "campaign own" on public.campaigns for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "lead own" on public.leads; create policy "lead own" on public.leads for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "automation own" on public.automations; create policy "automation own" on public.automations for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
